import{_ as a,o as r,c as i,ae as l}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"Implementation Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"sessions/20260226-helios-market-research/04_IMPLEMENTATION_STRATEGY.md","filePath":"sessions/20260226-helios-market-research/04_IMPLEMENTATION_STRATEGY.md"}'),t={name:"sessions/20260226-helios-market-research/04_IMPLEMENTATION_STRATEGY.md"};function o(n,e,s,c,d,h){return r(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="implementation-strategy" tabindex="-1">Implementation Strategy <a class="header-anchor" href="#implementation-strategy" aria-label="Permalink to &quot;Implementation Strategy&quot;">​</a></h1><h2 id="locked-architecture" tabindex="-1">Locked Architecture <a class="header-anchor" href="#locked-architecture" aria-label="Permalink to &quot;Locked Architecture&quot;">​</a></h2><ul><li>Language and packaging: <code>TS7-native</code>, prerelease-first dependency policy (<code>beta</code>/<code>rc</code>)</li><li>Shell: <code>ElectroBun</code></li><li>Renderer engines: <code>ghostty</code> and <code>rio</code></li><li>Worktree orchestrator: <code>par</code></li><li>Mux core: <code>zellij</code></li><li>Persistence/collab layer: <code>zmx</code> + <code>upterm</code> + <code>tmate</code></li><li>Protocols: <code>ACP</code> + <code>MCP</code> + <code>A2A</code> + internal local control bus</li></ul><h2 id="process-model" tabindex="-1">Process Model <a class="header-anchor" href="#process-model" aria-label="Permalink to &quot;Process Model&quot;">​</a></h2><ul><li>ElectroBun host process owns lifecycle, windows, settings, and policy gates.</li><li><code>par</code> manages worktree lane creation, assignment, and cleanup for agent tasks.</li><li>Renderer worker abstraction supports <code>ghostty</code> and <code>rio</code> backends.</li><li><code>zellij</code> session supervisor manages pane/tab topology per worktree lane.</li><li><code>zmx</code> tracks durable terminal process identities and restore metadata.</li><li><code>upterm</code> and <code>tmate</code> adapters expose explicit share sessions for selected terminals.</li><li>Internal control bus (local IPC) coordinates session, renderer, agent, and policy events.</li></ul><h2 id="renderer-feature-flag-design" tabindex="-1">Renderer Feature Flag Design <a class="header-anchor" href="#renderer-feature-flag-design" aria-label="Permalink to &quot;Renderer Feature Flag Design&quot;">​</a></h2><h3 id="settings-contract" tabindex="-1">Settings contract <a class="header-anchor" href="#settings-contract" aria-label="Permalink to &quot;Settings contract&quot;">​</a></h3><ul><li>Key: <code>renderer_engine</code></li><li>Allowed values: <code>ghostty</code>, <code>rio</code></li><li>Persisted scope: workspace default with global override</li></ul><h3 id="switch-flow" tabindex="-1">Switch flow <a class="header-anchor" href="#switch-flow" aria-label="Permalink to &quot;Switch flow&quot;">​</a></h3><ol><li>User changes renderer in settings.</li><li>Runtime performs capability check for target backend.</li><li>If hot swap supported:</li></ol><ul><li>suspend output streams briefly</li><li>remount renderer backend</li><li>replay visible screen buffers</li><li>resume streams</li></ul><ol start="4"><li>If hot swap unsupported:</li></ol><ul><li>display restart notice</li><li>checkpoint session state via <code>zmx</code> and <code>zellij</code></li><li>fast restart host</li><li>restore sessions automatically</li></ul><h3 id="safety-rules" tabindex="-1">Safety rules <a class="header-anchor" href="#safety-rules" aria-label="Permalink to &quot;Safety rules&quot;">​</a></h3><ul><li>Never drop PTY process state during renderer switch.</li><li>Switch operation is transactional; rollback to previous renderer on failure.</li></ul><h2 id="worktree-swarm-design-par" tabindex="-1">Worktree Swarm Design (<code>par</code>) <a class="header-anchor" href="#worktree-swarm-design-par" aria-label="Permalink to &quot;Worktree Swarm Design (`par`)&quot;">​</a></h2><h3 id="lane-model" tabindex="-1">Lane model <a class="header-anchor" href="#lane-model" aria-label="Permalink to &quot;Lane model&quot;">​</a></h3><ul><li>each task lane maps to: <ul><li>one git worktree</li><li>one zellij session namespace</li><li>one or more terminals tracked by zmx</li></ul></li></ul><h3 id="lane-lifecycle" tabindex="-1">Lane lifecycle <a class="header-anchor" href="#lane-lifecycle" aria-label="Permalink to &quot;Lane lifecycle&quot;">​</a></h3><ol><li><code>par</code> creates/selects worktree for task</li><li>runtime creates/attaches zellij session</li><li>terminals are registered with zmx</li><li>optional share session can be attached via upterm/tmate</li><li>lane completion triggers cleanup policy (archive/keep/prune)</li></ol><h3 id="guardrails" tabindex="-1">Guardrails <a class="header-anchor" href="#guardrails" aria-label="Permalink to &quot;Guardrails&quot;">​</a></h3><ul><li>max active lanes configurable by workspace</li><li>orphaned worktree/session detector runs periodically</li><li>cleanup actions must emit audit records</li></ul><h2 id="layered-responsibilities" tabindex="-1">Layered Responsibilities <a class="header-anchor" href="#layered-responsibilities" aria-label="Permalink to &quot;Layered Responsibilities&quot;">​</a></h2><h3 id="electrobun-shell" tabindex="-1">ElectroBun shell <a class="header-anchor" href="#electrobun-shell" aria-label="Permalink to &quot;ElectroBun shell&quot;">​</a></h3><ul><li>Settings, feature flags, app lifecycle, menu/command registration, secure storage access.</li></ul><h3 id="renderer-adapters" tabindex="-1">Renderer adapters <a class="header-anchor" href="#renderer-adapters" aria-label="Permalink to &quot;Renderer adapters&quot;">​</a></h3><ul><li>Terminal draw pipeline, input handling, resize propagation, clipboard hooks, semantic markers.</li></ul><h3 id="par-integration" tabindex="-1">par integration <a class="header-anchor" href="#par-integration" aria-label="Permalink to &quot;par integration&quot;">​</a></h3><ul><li>Worktree provisioning, branch/task lane mapping, lane lifecycle hooks.</li></ul><h3 id="zellij-integration" tabindex="-1">zellij integration <a class="header-anchor" href="#zellij-integration" aria-label="Permalink to &quot;zellij integration&quot;">​</a></h3><ul><li>Pane/tab/session orchestration and command routing.</li></ul><h3 id="zmx-integration" tabindex="-1">zmx integration <a class="header-anchor" href="#zmx-integration" aria-label="Permalink to &quot;zmx integration&quot;">​</a></h3><ul><li>Durable process/session persistence and crash recovery checkpoints.</li></ul><h3 id="upterm-tmate-integration" tabindex="-1">upterm/tmate integration <a class="header-anchor" href="#upterm-tmate-integration" aria-label="Permalink to &quot;upterm/tmate integration&quot;">​</a></h3><ul><li>Secure, user-approved share-session creation and termination.</li></ul><h3 id="protocol-runtime" tabindex="-1">Protocol runtime <a class="header-anchor" href="#protocol-runtime" aria-label="Permalink to &quot;Protocol runtime&quot;">​</a></h3><ul><li>ACP: client boundary adapter where supported by agents.</li><li>MCP: tool/resource interoperability.</li><li>A2A: external agent federation boundary.</li><li>internal bus: deterministic local command and event orchestration.</li></ul><h2 id="security-and-policy" tabindex="-1">Security and Policy <a class="header-anchor" href="#security-and-policy" aria-label="Permalink to &quot;Security and Policy&quot;">​</a></h2><ul><li>Share-session actions (<code>upterm</code>/<code>tmate</code>) are deny-by-default and require explicit user approval per terminal.</li><li>Command policy engine applies before any agent-mediated execution.</li><li>Sensitive paths and secrets are masked in logs and share surfaces.</li><li>Collaboration endpoints are ephemeral by default with configurable TTL.</li></ul><h2 id="performance-strategy" tabindex="-1">Performance Strategy <a class="header-anchor" href="#performance-strategy" aria-label="Permalink to &quot;Performance Strategy&quot;">​</a></h2><ul><li>Pre-allocate renderer buffers with upper bounds per terminal.</li><li>Backpressure on high-output streams.</li><li>Lazy rendering for inactive tabs/panes.</li><li>Session checkpoint batching for low-overhead zmx persistence.</li><li>Lane pooling and bounded worktree creation to avoid FS thrash.</li></ul><h2 id="delivery-plan" tabindex="-1">Delivery Plan <a class="header-anchor" href="#delivery-plan" aria-label="Permalink to &quot;Delivery Plan&quot;">​</a></h2><h3 id="phase-1" tabindex="-1">Phase 1 <a class="header-anchor" href="#phase-1" aria-label="Permalink to &quot;Phase 1&quot;">​</a></h3><ul><li>ElectroBun shell + par + zellij + single renderer (<code>ghostty</code>) baseline.</li></ul><h3 id="phase-2" tabindex="-1">Phase 2 <a class="header-anchor" href="#phase-2" aria-label="Permalink to &quot;Phase 2&quot;">​</a></h3><ul><li>Add <code>rio</code> backend and feature-flag switch flow.</li></ul><h3 id="phase-3" tabindex="-1">Phase 3 <a class="header-anchor" href="#phase-3" aria-label="Permalink to &quot;Phase 3&quot;">​</a></h3><ul><li>Integrate <code>zmx</code> durability and restart restoration.</li></ul><h3 id="phase-4" tabindex="-1">Phase 4 <a class="header-anchor" href="#phase-4" aria-label="Permalink to &quot;Phase 4&quot;">​</a></h3><ul><li>Integrate <code>upterm</code> and <code>tmate</code> share-session workflows.</li></ul><h3 id="phase-5" tabindex="-1">Phase 5 <a class="header-anchor" href="#phase-5" aria-label="Permalink to &quot;Phase 5&quot;">​</a></h3><ul><li>Harden protocol layer (ACP + MCP + A2A + internal bus), policy gates, and observability.</li></ul><h2 id="exit-criteria" tabindex="-1">Exit Criteria <a class="header-anchor" href="#exit-criteria" aria-label="Permalink to &quot;Exit Criteria&quot;">​</a></h2><ul><li>Dual-renderer switching works via hot swap or safe restart path.</li><li>25-terminal workload remains responsive.</li><li><code>par</code> lane lifecycle remains stable under swarm load.</li><li><code>zmx</code> restores sessions reliably after crash/restart.</li><li><code>upterm</code>/<code>tmate</code> handoff is stable and policy-controlled.</li></ul>',54)])])}const m=a(t,[["render",o]]);export{p as __pageData,m as default};
